Here is the extended C# code that maintains the existing functionality of printing the report summary and adds the capability to export the report in CSV format:

```csharp
using System;
using System.IO;
using System.Text;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportCsv = false, string filePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional feature: Export report in CSV format if requested
        if (exportCsv)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(filePath))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Assuming SummaryReport has a method or properties to extract data for CSV
                    // This is a placeholder implementation; adjust based on actual SummaryReport structure
                    var properties = report.GetType().GetProperties();
                    foreach (var prop in properties)
                    {
                        var value = prop.GetValue(report, null);
                        // Escape commas and quotes in values for proper CSV formatting
                        var escapedValue = value?.ToString()?.Replace("\"", "\"\"");
                        writer.WriteLine($"{prop.Name},\"{escapedValue}\"");
                    }
                }

                Console.WriteLine($"Report exported to CSV: {filePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

// Placeholder class for SummaryReport to make the code compile
public class SummaryReport
{
    public string Title { get; set; }
    public string Date { get; set; }
    public string Content { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nDate: {Date}\nContent: {Content}";
    }
}
